        /// <summary>
        /// Get documents by a specific reference
        /// </summary>
        /// <param name="reference">Reference</param>
        /// <returns>List of documents</returns>
        public List<ACDocumentsInfo> GetDocumentsForInputVAT(DateTime? fromDate, DateTime? toDate)
        {
            DataSet ds = dal.GetDataSet("ACDocuments_GetDocumentListForInputVAT", fromDate, toDate);
            //return (List<ACDocumentsInfo>)GetListFromDataSet(ds);
            List<ACDocumentsInfo> result = new List<ACDocumentsInfo>();

            if(ds != null && ds.Tables.Count != 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    ACDocumentsInfo document = GetObjectFromDataRow(row) as ACDocumentsInfo;
                    if (document.ACDocumentTotalAmount != 0)
                        document.ItemTaxPercent = document.DocumentTaxAmount * 100 / document.ACDocumentTotalAmount;
                    result.Add(document);
                }
            }

            return result;
        }

