        public List<ACDocumentsInfo> GetDocumentForGeneralSegmentReport(string accountNo, DateTime? fromDate, DateTime? toDate)
        {
            DataSet ds = dal.GetDataSet("ACDocuments_GetDocumentForGeneralSegmentReport", accountNo, fromDate, toDate);

            List<ACDocumentsInfo> documents = new List<ACDocumentsInfo>();
            if (ds.Tables.Count > 0)
            {
                foreach (DataRow row in ds.Tables[0].Rows)
                {
                    ACDocumentsInfo objDocumentsInfo = (ACDocumentsInfo)dal.GetObjectFromDataRow(row);
                    documents.Add(objDocumentsInfo);
                }
            }

            return documents;
        }
